ALTER TABLE public.clock_settings DROP CONSTRAINT IF EXISTS clock_settings_ogn_sync_interval_seconds_check; ALTER TABLE public.clock_settings ADD CONSTRAINT clock_settings_ogn_sync_interval_seconds_check CHECK (ogn_sync_interval_seconds >= 1 AND ogn_sync_interval_seconds <= 120); ALTER TABLE public.clock_settings ALTER COLUMN ogn_sync_interval_seconds SET DEFAULT 1; UPDATE public.clock_settings SET ogn_sync_interval_seconds = 1 WHERE id = 1 AND ogn_sync_interval_seconds = 2;